/**
 * Statistical primitives. Parity with statsmodels/scipy is checked in
 * tests/unit/parity.test.ts against fixtures generated by analytics/parity.
 */

export function mean(values: readonly number[]): number {
  if (values.length === 0) return Number.NaN;
  let sum = 0;
  for (const v of values) sum += v;
  return sum / values.length;
}

export function sampleVariance(values: readonly number[]): number {
  if (values.length < 2) return Number.NaN;
  const m = mean(values);
  let sum = 0;
  for (const v of values) sum += (v - m) ** 2;
  return sum / (values.length - 1);
}

/** Complementary error function, accurate to ~1e-15 relative for x >= 0. */
export function erfc(x: number): number {
  if (Number.isNaN(x)) return Number.NaN;
  if (x < 0) return 2 - erfc(-x);
  if (x < 2.5) {
    // Maclaurin series of erf(x); converges quickly for small x.
    const x2 = x * x;
    let term = x;
    let sum = x;
    for (let n = 1; n < 200; n += 1) {
      term *= -x2 / n;
      const add = term / (2 * n + 1);
      sum += add;
      if (Math.abs(add) < 1e-17 * Math.abs(sum)) break;
    }
    return 1 - (2 / Math.sqrt(Math.PI)) * sum;
  }
  if (x > 27) return 0;
  // Laplace continued fraction, evaluated with the modified Lentz algorithm:
  // erfc(x) = x e^{-x^2} / sqrt(pi) / (x^2 + (1/2)/(1 + 1/(x^2 + (3/2)/(1 + ...))))
  const tiny = 1e-300;
  const x2 = x * x;
  let f = x2;
  let c = f;
  let d = 0;
  for (let k = 1; k < 500; k += 1) {
    const a = k / 2;
    const b = k % 2 === 1 ? 1 : x2;
    d = b + a * d;
    if (Math.abs(d) < tiny) d = tiny;
    c = b + a / c;
    if (Math.abs(c) < tiny) c = tiny;
    d = 1 / d;
    const delta = c * d;
    f *= delta;
    if (Math.abs(delta - 1) < 1e-16) break;
  }
  return (x * Math.exp(-x2)) / Math.sqrt(Math.PI) / f;
}

/** Two-sided p-value of a standard normal statistic. */
export function normalTwoSidedP(z: number): number {
  return erfc(Math.abs(z) / Math.SQRT2);
}

export const Z_975 = 1.959963984540054;

const LANCZOS = [
  0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313, -176.61502916214059, 12.507343278686905,
  -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7,
];

export function lnGamma(z: number): number {
  if (z < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * z))) - lnGamma(1 - z);
  const zz = z - 1;
  let x = LANCZOS[0] as number;
  for (let i = 1; i < LANCZOS.length; i += 1) x += (LANCZOS[i] as number) / (zz + i);
  const t = zz + 7.5;
  return 0.5 * Math.log(2 * Math.PI) + (zz + 0.5) * Math.log(t) - t + Math.log(x);
}

function betaContinuedFraction(a: number, b: number, x: number): number {
  const tiny = 1e-300;
  const qab = a + b;
  const qap = a + 1;
  const qam = a - 1;
  let c = 1;
  let d = 1 - (qab * x) / qap;
  if (Math.abs(d) < tiny) d = tiny;
  d = 1 / d;
  let h = d;
  for (let m = 1; m <= 500; m += 1) {
    const m2 = 2 * m;
    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
    d = 1 + aa * d;
    if (Math.abs(d) < tiny) d = tiny;
    c = 1 + aa / c;
    if (Math.abs(c) < tiny) c = tiny;
    d = 1 / d;
    h *= d * c;
    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
    d = 1 + aa * d;
    if (Math.abs(d) < tiny) d = tiny;
    c = 1 + aa / c;
    if (Math.abs(c) < tiny) c = tiny;
    d = 1 / d;
    const delta = d * c;
    h *= delta;
    if (Math.abs(delta - 1) < 3e-16) break;
  }
  return h;
}

/** Regularized incomplete beta function I_x(a, b). */
export function incompleteBeta(x: number, a: number, b: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const front = Math.exp(lnGamma(a + b) - lnGamma(a) - lnGamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  if (x < (a + 1) / (a + b + 2)) return (front * betaContinuedFraction(a, b, x)) / a;
  return 1 - (front * betaContinuedFraction(b, a, 1 - x)) / b;
}

/** Two-sided p-value of a Student t statistic with df degrees of freedom. */
export function studentTwoSidedP(t: number, df: number): number {
  if (!Number.isFinite(t)) return Number.isNaN(t) ? Number.NaN : 0;
  return incompleteBeta(df / (df + t * t), df / 2, 0.5);
}

export interface OlsHacResult {
  slope: number;
  intercept: number;
  seSlope: number;
  z: number;
  pValue: number;
  ci95: [number, number];
  n: number;
  r2: number;
  residuals: number[];
}

/**
 * Ordinary least squares y = a + b x with Newey–West HAC standard errors.
 * Matches statsmodels `OLS(y, add_constant(x)).fit(cov_type="HAC",
 * cov_kwds={"maxlags": L})`: Bartlett kernel, no small-sample correction,
 * normal-based p-value and 95 % interval. x is centered internally, which
 * leaves the slope and its HAC variance unchanged.
 */
export function olsHac(x: readonly number[], y: readonly number[], maxlags = 1): OlsHacResult {
  const n = x.length;
  if (n !== y.length) throw new Error("x and y must have the same length");
  if (n < 3) throw new Error("At least three observations are required");
  const xMean = mean(x);
  const yMean = mean(y);
  const xc = x.map((v) => v - xMean);
  let sxx = 0;
  let sxy = 0;
  for (let i = 0; i < n; i += 1) {
    sxx += (xc[i] as number) ** 2;
    sxy += (xc[i] as number) * ((y[i] as number) - yMean);
  }
  if (sxx === 0) throw new Error("x has no variance");
  const slope = sxy / sxx;
  const interceptCentered = yMean;
  const residuals = y.map((v, i) => v - interceptCentered - slope * (xc[i] as number));

  // Slope element of the sandwich meat for the centered design [1, xc]:
  // sum e_t^2 xc_t^2 + sum_l w_l * 2 * sum_t e_t e_{t-l} xc_t xc_{t-l}.
  let s11 = 0;
  for (let t = 0; t < n; t += 1) {
    s11 += ((residuals[t] as number) * (xc[t] as number)) ** 2;
  }
  for (let lag = 1; lag <= maxlags; lag += 1) {
    const w = 1 - lag / (maxlags + 1);
    let cross = 0;
    for (let t = lag; t < n; t += 1) {
      cross += (residuals[t] as number) * (xc[t] as number) * (residuals[t - lag] as number) * (xc[t - lag] as number);
    }
    s11 += w * 2 * cross;
  }
  // Bread: (X'X)^-1 for the centered design is diag(1/n, 1/sxx).
  const varSlope = s11 / (sxx * sxx);
  const seSlope = Math.sqrt(Math.max(varSlope, 0));
  const z = slope / seSlope;
  let ssr = 0;
  let sst = 0;
  for (let i = 0; i < n; i += 1) {
    ssr += (residuals[i] as number) ** 2;
    sst += ((y[i] as number) - yMean) ** 2;
  }
  return {
    slope,
    intercept: yMean - slope * xMean,
    seSlope,
    z,
    pValue: normalTwoSidedP(z),
    ci95: [slope - Z_975 * seSlope, slope + Z_975 * seSlope],
    n,
    r2: sst > 0 ? 1 - ssr / sst : 0,
    residuals,
  };
}

/** Benjamini–Hochberg adjusted p-values (q-values), in the input order. */
export function benjaminiHochberg(pValues: readonly number[]): number[] {
  const m = pValues.length;
  const order = pValues.map((p, i) => ({ p, i })).sort((a, b) => a.p - b.p);
  const adjusted = new Array<number>(m);
  let running = 1;
  for (let k = m - 1; k >= 0; k -= 1) {
    const entry = order[k] as { p: number; i: number };
    running = Math.min(running, (entry.p * m) / (k + 1));
    adjusted[entry.i] = Math.min(1, running);
  }
  return adjusted;
}

export interface WelchResult {
  t: number;
  df: number;
  pValue: number;
  difference: number;
}

/** Welch's unequal-variance t-test for the difference of means (b - a). */
export function welchTTest(a: readonly number[], b: readonly number[]): WelchResult {
  const va = sampleVariance(a) / a.length;
  const vb = sampleVariance(b) / b.length;
  const difference = mean(b) - mean(a);
  const t = difference / Math.sqrt(va + vb);
  const df = (va + vb) ** 2 / (va ** 2 / (a.length - 1) + vb ** 2 / (b.length - 1));
  return { t, df, pValue: studentTwoSidedP(t, df), difference };
}
